    const handleToolClick = useCallback((tool: DiagramCreationTool) => {
        const definition = definitions.find((candidate) => candidate.tool === tool);
        if (!definition) throw new Error(`Diagram creation tool is unavailable: ${tool}`);

        activate(definition);
        setOpen(false);
        dropdownButton?.focus();
    }, [activate, definitions, dropdownButton]);
    const selectedLabel = selectedDefinition?.label ?? 'tool';

    return (
        <>
            <ButtonGroup aria-label="Add diagram object" size="small" variant="outlined">
                <Tooltip title={selectedDefinition ? `Add ${selectedDefinition.label}` : 'Choose an Add tool'}>
                    <span>
                        <Button
                            aria-label={`Add ${selectedLabel}`}
                            disabled={!selectedDefinition}
                            onClick={handleAdd}
                            startIcon={<AddOutlined />}
                            sx={{ height: 34 }}
                        >
                            Add
                        </Button>
                    </span>
                </Tooltip>
                <Tooltip title="Choose Add tool">
                    <Button
                        aria-expanded={open}
                        aria-haspopup="menu"
                        aria-label="Choose Add tool"
                        onClick={handleToggle}
                        ref={setDropdownButton}
                        sx={{ height: 34, minWidth: 34, px: 0.5 }}
                    >
                        <ArrowDropDownOutlined />
                    </Button>
                </Tooltip>
            </ButtonGroup>
            <Popper anchorEl={dropdownButton} open={open} placement="bottom-start" sx={{ zIndex: 'tooltip' }}>
                <ClickAwayListener onClickAway={handleClose}>
                    <Paper elevation={8} sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1.75, mt: 0.5 }}>
                        <MenuList aria-label="Add diagram tool" autoFocusItem={open} onKeyDown={handleMenuKeyDown}>
                            {definitions.map((definition) => {
                                const handleClick = () => handleToolClick(definition.tool);

                                return (
                                    <MenuItem key={`${definition.category}:${definition.tool}`} onClick={handleClick} selected={definition.tool === lastSelectedTool}>
                                        <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, minWidth: 120 }}>
                                            <DiagramCreationToolSample definition={definition} />
                                            {definition.label}
                                        </Box>
                                    </MenuItem>
                                );
                            })}
                        </MenuList>
                    </Paper>
                </ClickAwayListener>
            </Popper>
        </>
    );
}

import { Button, Tooltip } from '@mui/material';

interface DiagramToolboxButtonProps {
    active?: boolean;
    disabled?: boolean;
    label: string;
    onActivate: () => void;
    tooltip: string;
}

/** Accessible toolbox action whose visible label and tooltip describe its operation. */
export function DiagramToolboxButton({
    active,
    disabled = false,
    label,
    onActivate,
    tooltip,
}: DiagramToolboxButtonProps) {
    return (
        <Tooltip title={tooltip}>
            <span>
                <Button
                    aria-label={label}
                    aria-pressed={active}
                    disabled={disabled}
                    onClick={onActivate}
                    size="small"
                    variant={active ? 'contained' : 'outlined'}
                >
                    {label}
                </Button>
            </span>
        </Tooltip>
    );
}

import type { DiagramData, DiagramFlowPreset, DiagramType } from './diagram_data'

export type EmptyDiagramChoiceId = 'architecture' | 'dependency' | 'entity' | 'flowchart' | 'sequence' | 'state'

export interface EmptyDiagramChoice {
    description: string
    id: EmptyDiagramChoiceId
    label: string
    preset?: DiagramFlowPreset
    title: string
    type: DiagramType
}

export const EMPTY_DIAGRAM_CHOICES: readonly EmptyDiagramChoice[] = [
    { description: 'New architecture diagram', id: 'architecture', label: 'Architecture', title: 'New architecture', type: 'architecture' },
    { description: 'New dependency diagram', id: 'dependency', label: 'Dependency', title: 'New dependency', type: 'dependency' },
    { description: 'New sequence diagram', id: 'sequence', label: 'Sequence', title: 'New sequence', type: 'sequence' },
    { description: 'New flowchart diagram', id: 'flowchart', label: 'Flowchart', preset: 'flowchart', title: 'New flowchart', type: 'flow' },
    { description: 'New state diagram', id: 'state', label: 'State diagram', preset: 'state', title: 'New state diagram', type: 'flow' },
    { description: 'New entity diagram', id: 'entity', label: 'Entity', title: 'New entity', type: 'entity' },
]

/** Builds canonical persisted data for a new empty diagram. */
export function createEmptyDiagramData(choice: EmptyDiagramChoice): DiagramData {
    return {
        edges: [],
        groups: [],
        meta: {
            description: choice.description,
            ...(choice.preset ? { preset: choice.preset } : {}),
            title: choice.title,
            type: choice.type,
            version: 1,
        },
        nodes: [],
    }
}

import { describe, expect, it } from 'vitest'
import { parseDiagramData, serializeDiagramData } from './diagram_data'
import { createEmptyDiagramData, EMPTY_DIAGRAM_CHOICES } from './empty_diagram_factory'

describe('createEmptyDiagramData', () => {
    it.each(EMPTY_DIAGRAM_CHOICES)('creates valid empty $label data', (choice) => {
        const diagram = createEmptyDiagramData(choice)
        const parsed = parseDiagramData(serializeDiagramData(diagram))

        expect(parsed).toEqual(diagram)
        expect(diagram).toMatchObject({
            edges: [],
            groups: [],
            meta: {
                description: choice.description,
                title: choice.title,
                type: choice.type,
                version: 1,
            },
            nodes: [],
        })
        expect(diagram.meta.description.length).toBeGreaterThan(0)
        expect(diagram.meta.title.length).toBeGreaterThan(0)
        expect(diagram).not.toHaveProperty('fragments')
        expect(diagram.meta).not.toHaveProperty('legend')
    })

    it('stores separate flowchart and state presets', () => {
        const flowchart = EMPTY_DIAGRAM_CHOICES.find(({ id }) => id === 'flowchart')
        const state = EMPTY_DIAGRAM_CHOICES.find(({ id }) => id === 'state')
        if (!flowchart || !state) throw new Error('Flow diagram choices are required')

        expect(createEmptyDiagramData(flowchart).meta).toMatchObject({ preset: 'flowchart', type: 'flow' })
        expect(createEmptyDiagramData(state).meta).toMatchObject({ preset: 'state', type: 'flow' })
    })
})

