            height="100%"
            style={{ left: 0, overflow: 'visible', pointerEvents: 'none', position: 'absolute', top: 0, zIndex: 1 }}
            width="100%"
        >
            <path
                d={roundedDiagramPath([...preview.points] as DiagramWaypoint[])}
                fill="none"
                stroke={theme.palette.primary.main}
                strokeDasharray="6 4"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
            />
        </svg>
    )
}

